from pathlib import Path
p=Path('agent_notes/lbc_other_world_tech.md'); s=p.read_text(encoding='utf8')
edits={
'### `lbc:other/nexus/click/orb_gun/uncraft`':'Орб-ган входит в эту ветку при удержании sneak: луч продвигает игрока вперёд по `Distance`, пока не встретит предмет в пределах 2 блоков или блок не из `#minecraft:airs`; тогда вызывает `uncraft_at`. Каждый предмет поблизости помечается `uncrafted` и отдельно разбирается. Это лучевое действие, а не пассивная переработка инвентаря. [Источник](../world/datapacksdisabled/LBC/data/lbc/function/other/nexus/click/orb_gun/uncraft.mcfunction)',
'### `lbc:other/nexus/click/orb_gun/uncraft_at`':'В точке попадания функция выбирает предметные сущности в радиусе 2 и вызывает для каждой разбор; после этого продолжение луча ограничено `Distance ≤ 80` и идёт шагом 0,1 блока. Ветка по блоку тоже запускается при столкновении с небезвоздушным блоком, но сам блок эта функция не добывает. [Источник](../world/datapacksdisabled/LBC/data/lbc/function/other/nexus/click/orb_gun/uncraft_at.mcfunction)',
'### `lbc:other/nexus/click/orb_gun/uncraft_f`':'Для предметной сущности функция читает её `Item.id` и запускает таблицу обратного рецепта. Затем выдаёт частицы и расходует ровно одну единицу: стек из 1 уничтожается, больший стек уменьшается на 1 и функция вызывает себя снова. Поэтому каждый экземпляр обрабатывается отдельно; выход определяется идентификатором, а точные loot-выходы перечислены в [uncrafted-аудите](lbc_loot_uncrafted.md). [Источник](../world/datapacksdisabled/LBC/data/lbc/function/other/nexus/click/orb_gun/uncraft_f.mcfunction)',
'### `lbc:other/nexus/click/orb_gun/uncraft_f_2`':'Перед разбором функции хранится ID предмета и вызывается большая таблица выбора `uncrafted` loot. Этот вспомогательный файл лишь переходит к макросу выдачи опыта; он не решает входной рецепт. [Источник](../world/datapacksdisabled/LBC/data/lbc/function/other/nexus/click/orb_gun/uncraft_f_2.mcfunction)',
'### `lbc:other/nexus/click/orb_gun/uncraft_f_3`':'Макрос создаёт experience orb со значением из `storage lbc.math tmp1`; вызывающая ветка выбирает `tmp1` случайно из 1–3. [Источник](../world/datapacksdisabled/LBC/data/lbc/function/other/nexus/click/orb_gun/uncraft_f_3.mcfunction)',
'### `lbc:other/nexus/click/orb_gun/uncraft_f_loot_select`':'По сохранённому vanilla `Item.id` перебираются точные совпадения и выполняется один `return run loot spawn` с соответствующим рецептом. При отсутствии совпадения этот switch не подбирает близкий рецепт и не создаёт обычный выход. Полный список преобразований и точные количества лежат в [таблице uncrafted loot](lbc_loot_uncrafted.md). [Источник](../world/datapacksdisabled/LBC/data/lbc/function/other/nexus/click/orb_gun/uncraft_f_loot_select.mcfunction)'
}
for h,t in edits.items():
 if h not in s: print('MISSING',h); continue
 a=s.index(h)+len(h); b=s.find('\n### ',a); b=b if b>=0 else s.find('\n## ',a); b=b if b>=0 else len(s); s=s[:a]+'\n\n'+t+s[b:]
p.write_text(s,encoding='utf8')
